#include <iostream>
#include <string>
using namespace std;

int main() {
    int n;
    string inp;
    cin >> n >> inp;

    n = min(n, static_cast<int>(inp.size()));

    for (int i = 0; i + 1 < n; ++i) {
        if (inp[i] == inp[i + 1] && inp[i] != '?') {
            cout << "No\n";
            return 0;
        }
    }

    for (int i = 0; i < n; ++i) {
        if (i + 3 < n && inp[i] != '?' && inp[i + 3] != '?' &&
            inp[i] != inp[i + 3] && inp[i + 1] == inp[i + 2] &&
            inp[i + 1] == '?') {
            inp[i + 1] = inp[i + 2] = 'x';
        }

        if (i + 2 < n && inp[i] != '?' && inp[i + 2] != '?' &&
            inp[i + 2] != inp[i] && inp[i + 1] == '?') {
            inp[i + 1] = 'x';
        }
    }

    for (int i = 0; i < n; ++i) {
        if (inp[i] == '?') {
            cout << "Yes\n";
            return 0;
        }
    }

    cout << "No\n";
    return 0;
}

